const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point(-118.423217, 34.770153);
  const buffer_radius = 300; // meters
  const geometry = point.buffer(buffer_radius);

  const date_start = '2020-04-14';
  const date_end = '2020-04-15'; // 1-day window

  // 2. Data Acquisition
  let collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_SR')
    .filterDate(date_start, date_end)
    .filterBounds(geometry);

  // Check if collection is empty
  let collectionSize = await collection.size().getInfo();
  if (collectionSize === 0) {
    console.log("No Landsat 8 images found for 2020-04-14.");
    console.log("Trying a wider date window (April 2020)...");
    collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_SR')
      .filterDate('2020-04-01', '2020-04-30')
      .filterBounds(geometry);
    collectionSize = await collection.size().getInfo();
    if (collectionSize === 0) {
      console.log("No Landsat 8 images found for April 2020.");
      console.log("C1");
      return;
    }
  }

  // Cloud masking function for Landsat 8 SR, Collection 2, Tier 1
  function maskL8sr(image) {
    // Bits 0-1 are fill, 2 is cloud shadow, 3 is cloud, 4 is cirrus.
    const qaPixel = image.select('QA_PIXEL');
    const cloudShadowBitMask = (1 << 3);
    const cloudsBitMask = (1 << 5); // Corrected from 1<<3 and 1<<4 for C2 QA_PIXEL
    const cirrusBitMask = (1 << 6);

    // Both flags should be set to 0 for clear conditions.
    const mask = qaPixel.bitwiseAnd(cloudShadowBitMask).eq(0)
      .and(qaPixel.bitwiseAnd(cloudsBitMask).eq(0))
      .and(qaPixel.bitwiseAnd(cirrusBitMask).eq(0));

    // Apply the scaling factors to the appropriate bands.
    const opticalBands = image.select('SR_B[1-7]').multiply(0.0000275).add(-0.2);
    const thermalBand = image.select('ST_B10').multiply(0.00341802).add(149.0);

    return image.addBands(opticalBands, null, true)
      .addBands(thermalBand, null, true)
      .updateMask(mask)
      .copyProperties(image, ['system:time_start']);
  }

  const maskedCollection = collection.map(maskL8sr);

  // Take the median composite to minimize residual clouds if multiple images are available
  const composite = maskedCollection.median();

  if (!composite) {
    console.log("C3"); // Should not happen if collectionSize > 0, but a safeguard.
    return;
  }

  // 3. Processing & Calculation
  // Calculate NDWI (Normalized Difference Water Index using Green and NIR)
  // NDWI = (Green - NIR) / (Green + NIR)
  // Landsat 8 bands: Green=B3, NIR=B5
  const ndwi = composite.normalizedDifference(['SR_B3', 'SR_B5']).rename('NDWI');

  // Calculate NDVI (Normalized Difference Vegetation Index)
  // NDVI = (NIR - Red) / (NIR + Red)
  // Landsat 8 bands: Red=B4, NIR=B5
  const ndvi = composite.normalizedDifference(['SR_B5', 'SR_B4']).rename('NDVI');

  // Select SWIR1 band for additional analysis
  // Landsat 8 band: SWIR1=B6
  const swir1 = composite.select('SR_B6').rename('SWIR1_Reflectance');

  // Combine bands for reduction
  const analysisImage = composite.addBands(ndwi).addBands(ndvi).addBands(swir1);

  // Reduce region to get mean values
  const scale = 30; // Landsat resolution
  const reduction = await analysisImage.reduceRegion({
    reducer: ee.Reducer.mean().setOutputs(['SR_B3', 'SR_B5', 'SR_B6', 'NDWI', 'NDVI']),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  if (!reduction || Object.values(reduction).some(val => val === null)) {
    console.log("C3"); // Reduction failed or returned null values
    return;
  }

  const meanNDWI = reduction.NDWI;
  const meanNDVI = reduction.NDVI;
  const meanSWIR1 = reduction.SWIR1_Reflectance;
  const meanGreen = reduction.SR_B3;
  const meanNIR = reduction.SR_B5;

  // Check for valid pixels
  const pixelCount = await analysisImage.select('SR_B3').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('SR_B3').getInfo();

  if (pixelCount === 0) {
    console.log("No valid pixels after cloud masking.");
    console.log("C2");
    return;
  }

  // 4. Validation & Final Answer Logic
  let isWater = false;
  let isSolarFarm = false;

  // Typical spectral signatures:
  // Water: High NDWI (>0.2), very low NIR (e.g., <0.05), very low SWIR1 (e.g., <0.03).
  // Solar Farm: Low NIR, low SWIR1 (often darker than water in some bands, but not always), low/negative NDVI, low NDWI.
  // Solar panels are designed to absorb light, so their reflectance in general tends to be very low across visible and NIR.

  // Thresholds based on general characteristics:
  // For water:
  // - NDWI > 0.2 (strong indicator of water)
  // - NIR reflectance < 0.05 (water absorbs NIR strongly)
  // - SWIR1 reflectance < 0.03 (water absorbs SWIR strongly)

  // For solar farm (distinguished from water):
  // - Low NDWI (e.g., < 0.1)
  // - Low NIR reflectance (similar to water, but maybe slightly higher than typical very clear water)
  // - SWIR1 reflectance potentially higher than very clear water, or similar if panels are very dark/absorptive.
  // - Very low NDVI (since it's not vegetation)

  // Solar farms often appear very dark and have very low reflectance across most bands,
  // making them spectrally somewhat similar to water but without the very strong water absorption
  // in SWIR bands that's characteristic of deep, clear water. However, NDWI (Green, NIR) will differentiate.

  // Let's use NDWI and SWIR1 reflectance as primary indicators.
  // Water is characterized by high NDWI and very low SWIR1 reflectance.
  // Solar farms will have lower NDWI and potentially slightly higher (though still low) SWIR1 reflectance compared to water.
  // Also, solar panels will typically have a very low to negative NDVI.

  console.log(`NDWI: ${meanNDWI.toFixed(3)}`);
  console.log(`NDVI: ${meanNDVI.toFixed(3)}`);
  console.log(`SWIR1 Reflectance: ${meanSWIR1.toFixed(3)}`);
  console.log(`NIR Reflectance: ${meanNIR.toFixed(3)}`);
  console.log(`Green Reflectance: ${meanGreen.toFixed(3)}`);
  console.log(`Valid Pixels: ${pixelCount}`);

  // Criteria for water pond:
  // High NDWI and strong absorption in NIR/SWIR1
  if (meanNDWI > 0.15 && meanNIR < 0.08 && meanSWIR1 < 0.05) { // More robust thresholds for potentially turbid/shallow water
    isWater = true;
  }

  // Criteria for solar farm (or non-water dark surface):
  // Low NDWI, low NDVI, low reflectance across bands, not meeting water criteria.
  // Solar panels are generally very dark across visible and NIR.
  if (meanNDWI < 0.15 && meanNDVI < 0.1 && meanNIR < 0.1 && meanSWIR1 < 0.1) { // Low values across the board, not fitting water's strong SWIR absorption
    // This is a rough distinction. Solar farms will typically be very dark, low reflectance overall.
    // The key is distinguishing from water. If it's not strongly 'water-like', then it's likely something else dark.
    if (!isWater) { // If it's not classified as water, and it's dark
      isSolarFarm = true;
    }
  }

  // The coordinates (34.770153, -118.423217) are near the Rosamond Solar Center.
  // Expecting it to be a solar farm.

  // Refining logic based on typical solar farm appearance vs water:
  // Solar farms tend to have very low, but not zero, NIR/SWIR reflectance values.
  // Water has extremely low NIR/SWIR reflectance and very high NDWI.
  // If NDWI is moderately low and reflectances are low, it leans towards solar farm.

  // Let's adjust thresholds for stronger differentiation.
  // Very high NDWI (e.g., > 0.25) is strong water.
  // Very low SWIR1 (e.g., < 0.03) is strong water.
  if (meanNDWI > 0.25 || (meanNDWI > 0.15 && meanSWIR1 < 0.03)) { // Stronger water signal
    console.log("Interpretation: Consistent with a water pond.");
    console.log("B");
  } else if (meanNDWI < 0.15 && meanNDVI < 0.1 && meanNIR < 0.1 && meanSWIR1 > 0.03 && meanSWIR1 < 0.15) {
    // This looks like a dark, non-vegetated, non-strong-water surface.
    // The SWIR1 range (0.03 to 0.15) is key to differentiate from very clear water,
    // which would typically be <0.03.
    console.log("Interpretation: Consistent with a solar farm.");
    console.log("A");
  } else {
    // Default to 'No' if not strongly a solar farm, or if ambiguous.
    console.log("Interpretation: Ambiguous or not clearly a solar farm based on criteria.");
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
